def semver_sort(versions):
    def parse_version(v):
        # Split build metadata
        if '+' in v:
            v_without_build, build = v.split('+', 1)
        else:
            v_without_build = v
            build = ''

        # Split pre-release
        if '-' in v_without_build:
            version_part, prerelease = v_without_build.split('-', 1)
        else:
            version_part = v_without_build
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = version_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease is not None:
            identifiers = prerelease.split('.')
            prerelease_identifiers = []
            for identifier in identifiers:
                if identifier.isdigit():
                    prerelease_identifiers.append((0, int(identifier)))
                else:
                    prerelease_identifiers.append((1, identifier))
        else:
            prerelease_identifiers = None

        return (major, minor, patch, prerelease_identifiers)

    def compare_prerelease(pre1, pre2):
        # If both have no pre-release
        if pre1 is None and pre2 is None:
            return 0
        # If one has pre-release and other doesn't, pre-release comes first
        if pre1 is None:
            return 1
        if pre2 is None:
            return -1

        # Compare identifiers left to right
        for i in range(max(len(pre1), len(pre2))):
            if i >= len(pre1):
                return -1  # fewer identifiers sorts first
            if i >= len(pre2):
                return 1

            type1, val1 = pre1[i]
            type2, val2 = pre2[i]

            # All-digit identifiers sort before other identifiers
            if type1 != type2:
                return type1 - type2

            # Compare values
            if val1 < val2:
                return -1
            elif val1 > val2:
                return 1

        return 0

    parsed = [(parse_version(v), i, v) for i, v in enumerate(versions)]

    def sort_key(item):
        (major, minor, patch, prerelease), original_index, original_version = item
        # Return tuple for sorting: (major, minor, patch, prerelease_tuple, original_index)
        # For prerelease comparison, we need a sortable representation
        if prerelease is None:
            prerelease_sort = (1,)  # Sorts after pre-releases
        else:
            prerelease_sort = (0,) + tuple(prerelease)
        return (major, minor, patch, prerelease_sort, original_index)

    sorted_versions = sorted(parsed, key=sort_key)
    return [v for _, _, v in sorted_versions]

